<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);$env=[];
foreach(file($root.'/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){if(str_starts_with(trim($line),'#'))continue;[$key,$value]=array_pad(explode('=', $line,2),2,'');$env[trim($key)]=trim($value,' "');}
if(!in_array($env['DB_HOST']??'', ['localhost','127.0.0.1'],true))throw new RuntimeException('Local database only.');
$db=new PDO('mysql:host='.$env['DB_HOST'].';dbname='.$env['DB_DATABASE'].';charset=utf8mb4',$env['DB_USERNAME'],$env['DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec("SET time_zone = '+00:00'");$base=rtrim($env['APP_URL'],'/');$email='demo@admin.com';$password='demo';
$q=$db->prepare('SELECT u.id,u.restaurant_id FROM users u JOIN restaurants r ON r.id=u.restaurant_id WHERE u.email=? AND u.role="RESTAURANT_ADMIN" AND u.is_active=1 AND r.is_active=1');$q->execute([$email]);$manager=$q->fetch();if(!$manager)throw new RuntimeException('Local demo manager unavailable.');
$rid=(int)$manager['restaurant_id'];$q=$db->prepare('SELECT * FROM restaurant_pos_settings WHERE restaurant_id=?');$q->execute([$rid]);$original=$q->fetch();$orderIds=[];$tipInvoiceId=0;
$curl=curl_init();curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false]);
function pendingRequest(string $path,?array $fields=null,array $headers=[]):array{global $curl,$base;curl_setopt($curl,CURLOPT_URL,$base.$path);curl_setopt($curl,CURLOPT_HTTPHEADER,$headers);if($fields===null)curl_setopt($curl,CURLOPT_HTTPGET,true);else{curl_setopt($curl,CURLOPT_POST,true);curl_setopt($curl,CURLOPT_POSTFIELDS,$fields);} $body=curl_exec($curl);if($body===false)throw new RuntimeException(curl_error($curl));return [(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE),(string)$body];}
function pendingCheck(bool $ok,string $label):void{if(!$ok)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;}
try{
    $q=$db->prepare('INSERT INTO restaurant_pos_settings(restaurant_id,pos_enabled,manager_bill_edit_enabled) VALUES(?,1,0) ON DUPLICATE KEY UPDATE pos_enabled=1');$q->execute([$rid]);
    foreach([['DELIVERY','READY'],['TAKEAWAY','READY'],['DELIVERY','PREPARING']] as [$type,$status]){$number='QA-PENDING-'.strtoupper(bin2hex(random_bytes(4)));$key=hash('sha256',random_bytes(32));$q=$db->prepare('INSERT INTO orders(restaurant_id,order_number,special_request,total,status,idempotency_key,source,order_type,created_at,updated_at) VALUES(?,?,"Pending-ready test",100,?,?,"POS",?,UTC_TIMESTAMP(),UTC_TIMESTAMP())');$q->execute([$rid,$number,$status,$key,$type]);$orderIds[]=(int)$db->lastInsertId();}
    [$code]=pendingRequest('/r-owner/login',['email'=>$email,'password'=>$password]);pendingCheck($code===302,'temporary manager login');
    [$code,$html]=pendingRequest('/r-owner/pos');preg_match('~<script type="application/json" id="pos-config">(.*?)</script>~s',$html,$match);$config=json_decode($match[1]??'{}',true);pendingCheck($code===200&&!empty($config['csrf']),'POS session and CSRF token available');
    $number='QA-TIP-'.strtoupper(bin2hex(random_bytes(4)));$key=hash('sha256',random_bytes(32));$q=$db->prepare('INSERT INTO orders(restaurant_id,order_number,special_request,total,status,idempotency_key,source,order_type,created_at,updated_at) VALUES(?,? ,"Tip test",100,"COMPLETED",?,"POS","DINE_IN",UTC_TIMESTAMP(),UTC_TIMESTAMP())');$q->execute([$rid,$number,$key]);$tipOrderId=(int)$db->lastInsertId();$orderIds[]=$tipOrderId;
    $q=$db->prepare('INSERT INTO pos_invoices(restaurant_id,order_id,invoice_number,subtotal,discount,service_charge,tax,packaging_charge,delivery_charge,total,paid_total,payment_status,generated_by,created_at,updated_at) VALUES(?,?,?,100,0,0,0,0,0,100,100,"PAID",?,UTC_TIMESTAMP(),UTC_TIMESTAMP())');$q->execute([$rid,$tipOrderId,'QA-INV-'.strtoupper(bin2hex(random_bytes(4))),(int)$manager['id']]);$tipInvoiceId=(int)$db->lastInsertId();
    [$code,$body]=pendingRequest('/r-owner/api/pos/tip',['invoice_id'=>$tipInvoiceId,'amount'=>'15.50'],['X-CSRF-Token: '.$config['csrf']]);$tipResult=json_decode($body,true);pendingCheck($code===200&&($tipResult['tip_amount']??null)==='15.50','Restaurant owner can record a tip on a paid bill');
    [$code,$body]=pendingRequest('/r-owner/api/pos/tip',['invoice_id'=>$tipInvoiceId,'amount'=>'20.50'],['X-CSRF-Token: '.$config['csrf']]);$tipResult=json_decode($body,true);pendingCheck($code===200&&($tipResult['tip_amount']??null)==='20.50','Restaurant owner can update the saved tip');
    [$code,$body]=pendingRequest('/r-owner/api/pos/order-details?id='.$tipOrderId);$tipDetails=json_decode($body,true);pendingCheck($code===200&&($tipDetails['order']['tip_amount']??null)==='20.50'&&($tipDetails['order']['invoice_total']??null)==='100.00','Updated tip appears separately from the unchanged bill total');
    $today=(new DateTimeImmutable('now',new DateTimeZone('Asia/Colombo')))->format('Y-m-d');[$code,$body]=pendingRequest('/r-owner/api/pos/reports?from='.$today.'&to='.$today);$tipReport=json_decode($body,true);pendingCheck($code===200&&(float)($tipReport['summary']['tips']??0)>=20.5,'Tip amount is reported separately for the selected period');
    [$code,$body]=pendingRequest('/r-owner/api/pos/orders?view=payments');$result=json_decode($body,true);$shown=array_map('intval',array_column($result['orders']??[],'id'));
    pendingCheck($code===200&&in_array($orderIds[0],$shown,true),'Unbilled READY delivery appears in Pending Bills');
    pendingCheck($code===200&&in_array($orderIds[1],$shown,true),'Unbilled READY pickup appears in Pending Bills');
    pendingCheck($code===200&&!in_array($orderIds[2],$shown,true),'Unbilled delivery before READY stays out of Pending Bills');
    $script=file_get_contents($root.'/public/assets/pos.js');pendingCheck(str_contains($script,"!order.invoice_id&&isUnbilledReadyOrder(order)"),'Unbilled READY orders can generate a bill and proceed to payment from order details');
    pendingCheck(str_contains($html,'id="pos-header-description"'),'POS heading has a dynamic description target');
    pendingCheck(str_contains($html,'id="pos-orders-description"'),'orders section has a description target');
    pendingCheck(str_contains($script,'These are orders whose bills have been fully paid.')&&str_contains($script,'This list includes unpaid or partially paid invoices, plus unbilled Dine-In orders at Ready or Served and unbilled Pickup/Delivery orders at Ready. Open any order here to generate its bill and collect payment.'),'Paid Bills and Pending Bills have specific explanatory copy');
    pendingCheck(str_contains($script,"tipButton.textContent=Number(order.tip_amount||0)>0?'Update tip':'Add a tip'")&&str_contains($script,"['Tips',amount(report.summary.tips),'tip'"),'Paid bill tip editor and separate report metric are present');
    pendingCheck(str_contains($script,"closeOnBackdrop($('pos-order-dialog'))")&&str_contains($script,"closeOnBackdrop($('pos-preview-dialog'))")&&str_contains($script,"closeOnBackdrop($('pos-bill-edit'))")&&str_contains($script,"$('pos-alert').addEventListener('click',event=>closeBackdropFromEvent(event))")&&str_contains($script,"$('pos-payment-dialog').addEventListener('click',event=>closeBackdropFromEvent(event"),'Order details and other POS dialogs close on backdrop clicks');
    $navigation=file_get_contents($root.'/public/assets/backend-navigation.js');$dashboard=file_get_contents($root.'/public/dashboard.php');
    pendingCheck(str_contains($navigation,"event.data?.type==='restaurant-pos-heading'")&&str_contains($dashboard,'Create orders, prepare bills and receive payments.'),'Manager workspace heading receives the active POS view title and description');
}finally{
    if($orderIds){$delete=$db->prepare('DELETE FROM orders WHERE id=? AND restaurant_id=?');foreach($orderIds as $id)$delete->execute([$id,$rid]);}
    if($original){$q=$db->prepare('UPDATE restaurant_pos_settings SET pos_enabled=?,manager_bill_edit_enabled=?,updated_by=? WHERE restaurant_id=?');$q->execute([$original['pos_enabled'],$original['manager_bill_edit_enabled'],$original['updated_by'],$rid]);}else{$q=$db->prepare('DELETE FROM restaurant_pos_settings WHERE restaurant_id=?');$q->execute([$rid]);}
    curl_close($curl);echo "Temporary Pending Bills orders removed; original POS settings restored.\n";
}
